ext('c12_geo_ch2',[
C("🌍","जनसंख्या के आँकड़े कहाँ से आते हैं",["जनगणना: हर दस साल","नमूना सर्वेक्षण","जन्म-मृत्यु पंजीकरण","भारत में पहली जनगणना 1872"],"जनसंख्या के आँकड़े कई स्रोतों से मिलते हैं। सबसे भरोसेमंद स्रोत जनगणना है, जिसमें हर घर जाकर गिनती होती है। भारत में हर दस साल पर जनगणना होती है। इसके अलावा नमूना सर्वेक्षण और जन्म तथा मृत्यु के पंजीकरण से भी जानकारी मिलती है। भारत में पहली क्रमबद्ध जनगणना अठारह सौ इकहत्तर के आसपास शुरू हुई। इन आँकड़ों से सरकार स्कूल, अस्पताल और राशन की योजना बनाती है।"),
Q("जनगणना भारत में कितने वर्ष में होती है?","हर 10 वर्ष में","याद कीजिए... भारत में जनगणना हर दस साल में होती है, यानी दशक में एक बार। अलग-अलग वर्षों के आँकड़ों की तुलना करके हम देखते हैं कि आबादी कितनी बढ़ी और किस तरफ़ बढ़ी।"),
C("⛰️","वितरण को प्रभावित करने वाले भौतिक कारक",["जलवायु: सम और आरामदायक","भूमि: मैदान घने, पहाड़ विरल","मिट्टी: उपजाऊ जलोढ़","जल की उपलब्धता"],"जहाँ जीवन आसान है, वहाँ लोग ज़्यादा रहते हैं। मैदानी इलाक़ों में खेती और यातायात आसान होता है, इसलिए गंगा के मैदान में आबादी बहुत घनी है। पहाड़, रेगिस्तान और बहुत ठंडे इलाक़ों में कम लोग रहते हैं। उपजाऊ जलोढ़ मिट्टी और पानी की आसान उपलब्धता भी लोगों को खींचती है। इसीलिए सभ्यताएँ नदियों के किनारे पनपीं, जैसे सिंधु और गंगा की घाटी।"),
Q("गंगा का मैदान घना क्यों बसा है?","उपजाऊ मिट्टी, पर्याप्त जल, समतल भूमि और अनुकूल जलवायु के कारण","कारण सोचिए... यहाँ की जलोढ़ मिट्टी बहुत उपजाऊ है, नदियों से पानी आसानी से मिलता है, भूमि समतल है इसलिए सड़क और रेल बनाना सरल है, और जलवायु भी खेती के अनुकूल है। इन सभी कारणों से यहाँ आबादी बहुत घनी है।"),
C("🏭","आर्थिक और सामाजिक कारक",["खनिज और उद्योग","नगरीकरण","परिवहन के साधन","राजनीतिक स्थिरता"],"सिर्फ़ प्रकृति ही नहीं, आर्थिक कारण भी आबादी तय करते हैं। जहाँ खनिज मिलते हैं और उद्योग लगते हैं, वहाँ रोज़गार के लिए लोग आकर बस जाते हैं, जैसे झारखंड में जमशेदपुर और धनबाद। नगरों में सुविधाएँ ज़्यादा होती हैं, इसलिए लोग शहरों की ओर जाते हैं। अच्छा परिवहन, शांति और सरकार की नीतियाँ भी लोगों को बसने में मदद करती हैं। जहाँ युद्ध या अशांति हो, वहाँ से लोग पलायन करते हैं।"),
Q("दो आर्थिक कारक बताइए जो जनसंख्या वितरण को प्रभावित करते हैं।","खनिज/उद्योग और परिवहन (या नगरीकरण)","सोचिए... उद्योग लगने से रोज़गार बढ़ता है और लोग वहाँ बसते हैं। परिवहन साधन अच्छे हों तो व्यापार बढ़ता है और बस्तियाँ फैलती हैं। इसलिए खनिज और उद्योग तथा परिवहन दो मुख्य आर्थिक कारक हैं।"),
C("📏","घनत्व: सूत्र और प्रकार",["घनत्व = जनसंख्या ÷ क्षेत्रफल","अंकगणितीय घनत्व","शारीरिक घनत्व","कृषि घनत्व"],"घनत्व बताता है कि प्रति वर्ग किलोमीटर कितने लोग रहते हैं। सूत्र है कुल जनसंख्या भाग कुल क्षेत्रफल। इसे अंकगणितीय घनत्व कहते हैं। शारीरिक घनत्व में जनसंख्या को केवल खेती योग्य भूमि से भाग देते हैं, इसलिए यह जीवन के दबाव को बेहतर दिखाता है। कृषि घनत्व में कृषकों की संख्या को शुद्ध बोए गए क्षेत्र से भाग देते हैं। विकासशील देशों में शारीरिक घनत्व अकसर ज़्यादा होता है।"),
Q("किसी राज्य की जनसंख्या 12 करोड़ और क्षेत्रफल 1 लाख वर्ग किमी है। घनत्व क्या होगा?","12,00,00,000 ÷ 1,00,000 = 1200 व्यक्ति प्रति वर्ग किमी","सूत्र लगाइए... जनसंख्या बारह करोड़ और क्षेत्रफल एक लाख वर्ग किलोमीटर। बारह करोड़ को एक लाख से भाग देने पर बारह सौ आता है। यानी हर वर्ग किलोमीटर में बारह सौ लोग रहते हैं। यह घना क्षेत्र है।"),
C("📈","वृद्धि के घटक: जन्म, मृत्यु, प्रवास",["प्राकृतिक वृद्धि = जन्म दर − मृत्यु दर","प्रवास: आव्रजन और उत्प्रवास","वास्तविक वृद्धि = प्राकृतिक + प्रवास","धनात्मक और ऋणात्मक वृद्धि"],"जनसंख्या तीन बातों से बदलती है, जन्म, मृत्यु और प्रवास। प्राकृतिक वृद्धि जन्म दर में से मृत्यु दर घटाने पर मिलती है। प्रवास में बाहर से आने को आव्रजन और बाहर जाने को उत्प्रवास कहते हैं। इन दोनों को जोड़कर वास्तविक वृद्धि निकलती है। अगर जन्म दर मृत्यु दर से ज़्यादा है तो वृद्धि धनात्मक है, और अगर कम है तो जनसंख्या घट भी सकती है, जैसे कुछ यूरोपीय देशों में।"),
Q("जन्म दर 25 और मृत्यु दर 10 प्रति हज़ार हो तो प्राकृतिक वृद्धि दर?","25 − 10 = 15 प्रति हज़ार (1.5%)","घटाइए... जन्म दर पच्चीस में से मृत्यु दर दस घटाने पर पंद्रह आता है। यह प्रति हज़ार की दर है, यानी डेढ़ प्रतिशत। इतनी दर से आबादी बढ़ती रहे तो कुछ दशकों में दुगुनी हो जाती है।"),
C("🔄","जनांकिकीय संक्रमण के चरण",["पहला: उच्च जन्म, उच्च मृत्यु","दूसरा: मृत्यु घटी, जन्म ऊँचा","तीसरा: दोनों घट रहे","चौथा: निम्न जन्म, निम्न मृत्यु"],"जनांकिकीय संक्रमण में देश की आबादी चार चरणों से गुज़रती है। पहले चरण में जन्म और मृत्यु दोनों ऊँचे होते हैं, इसलिए जनसंख्या धीमी बढ़ती है। दूसरे में स्वास्थ्य सुधरता है, मृत्यु दर घटती है पर जन्म दर ऊँची रहती है, इसलिए तेज़ वृद्धि होती है। तीसरे चरण में जन्म दर भी घटने लगती है। चौथे में दोनों कम हो जाते हैं और आबादी स्थिर रहती है। भारत अभी दूसरे और तीसरे चरण के बीच माना जाता है।"),
Q("दूसरे चरण में जनसंख्या तेज़ी से क्यों बढ़ती है?","मृत्यु दर घट जाती है पर जन्म दर ऊँची रहती है","सोचिए... चिकित्सा और स्वच्छता सुधरने से लोग कम मरते हैं, पर परिवार छोटे रखने की आदत तुरंत नहीं बदलती। इसलिए जन्म दर ऊँची और मृत्यु दर नीची रहती है। इसी अंतर से जनसंख्या तेज़ी से बढ़ती है।"),
C("👪","आयु संरचना और जनसंख्या पिरामिड",["0–14: बाल","15–59: कार्यशील","60+: वृद्ध","चौड़ा आधार: तेज़ वृद्धि"],"आयु के आधार पर जनसंख्या तीन भागों में बाँटी जाती है। शून्य से चौदह साल के बच्चे, पंद्रह से उनसठ साल के कामकाजी लोग और साठ साल से ऊपर के बुज़ुर्ग। जनसंख्या पिरामिड में नीचे का आधार चौड़ा हो तो आबादी तेज़ी से बढ़ रही है, जैसे भारत में। पिरामिड बीच से चौड़ा और ऊपर से भारी हो तो वृद्ध ज़्यादा हैं, जैसे जापान में। कामकाजी लोग ज़्यादा हों तो इसे जनसांख्यिकीय लाभांश कहते हैं।"),
Q("जनसांख्यिकीय लाभांश क्या है?","कामकाजी आयु वर्ग की अधिकता से मिलने वाला आर्थिक लाभ","सोचिए... जब किसी देश में कमाने वाले युवा ज़्यादा हों और निर्भर बच्चे-बुज़ुर्ग कम, तो अर्थव्यवस्था तेज़ी से बढ़ सकती है। इसे जनसांख्यिकीय लाभांश कहते हैं। पर इसके लिए रोज़गार और अच्छी शिक्षा ज़रूरी है, वरना यह बोझ बन सकता है।"),
C("🏙️","नगरीकरण और प्रवास",["खिंचाव और धक्का कारक","गाँव से शहर","रोज़गार और शिक्षा","समस्या: झुग्गियाँ और प्रदूषण"],"लोग क्यों घर छोड़ते हैं? धक्का कारक हैं बेरोज़गारी, बाढ़ और ग़रीबी, जो गाँव से लोगों को धकेलते हैं। खिंचाव कारक हैं रोज़गार, शिक्षा और बेहतर सुविधाएँ, जो शहर की ओर खींचते हैं। बिहार से बहुत से लोग दिल्ली और मुंबई जाते हैं। इससे शहर फैलते हैं, पर झुग्गियाँ, भीड़ और प्रदूषण जैसी समस्याएँ भी बढ़ती हैं। इसलिए गाँवों में रोज़गार बढ़ाना ज़रूरी है।"),
Q("प्रवास के दो धक्का कारक और दो खिंचाव कारक बताइए।","धक्का: बेरोज़गारी, बाढ़; खिंचाव: रोज़गार, बेहतर शिक्षा","दो-दो कारण सोचिए... धक्का कारक गाँव की कठिनाइयाँ हैं, जैसे बेरोज़गारी और बाढ़। खिंचाव कारक शहर के आकर्षण हैं, जैसे नौकरी और अच्छे स्कूल-अस्पताल। यह जोड़ी बनाकर लिखेंगे तो पूरे अंक मिलेंगे।"),
C("✍️","उत्तर लिखने की तैयारी",["परिभाषा और सूत्र","आँकड़े और उदाहरण","मानचित्र / पिरामिड","संतुलित निष्कर्ष"],"इस अध्याय में सूत्र और आँकड़े अहम हैं। घनत्व और प्राकृतिक वृद्धि के सूत्र ज़रूर याद रखिए और प्रश्न हल करते समय हर चरण लिखिए। दीर्घ उत्तर में कारकों को भौतिक, आर्थिक और सामाजिक शीर्षकों में बाँटिए। जनांकिकीय संक्रमण की चारों अवस्थाएँ चित्र बनाकर समझाइए। अंत में एक पंक्ति में लिखिए कि संसाधन और जनसंख्या के बीच संतुलन ही सतत विकास की कुंजी है।"),
],7)
